={
  "from": "Yash <yash@yashsarnaik.in>",
  "to": [
    "yashsarnaik2303@gmail.com"
  ],
  "subject": "New lead received",
  "html": "<!DOCTYPE html> <html lang=\"en\"> <head> <meta charset=\"UTF-8\"> <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"> <title>New Lead Received</title> </head> <body style=\"margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;\"> <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#f4f6f8;padding:24px 0;\"> <tr> <td align=\"center\"> <table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"max-width:600px;width:100%;background-color:#ffffff;border-radius:8px;overflow:hidden;border:1px solid #e3e8ee;\"> <tr> <td style=\"background-color:#1f4fd8;padding:24px 32px;\"> <p style=\"margin:0;font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#c9d6ff;\">onPoint Software Services</p> <h1 style=\"margin:6px 0 0;font-size:22px;color:#ffffff;font-weight:bold;\">New Lead Received</h1> </td> </tr> <tr> <td style=\"padding:24px 32px 8px;\"> <p style=\"margin:0;font-size:15px;line-height:22px;color:#333333;\"> A new lead has just come in. Details below. </p> </td> </tr> <tr> <td style=\"padding:8px 32px 24px;\"> <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"font-size:14px;color:#333333;\"> <tr> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;width:35%;color:#6b7785;\">Lead ID</td> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;font-weight:bold;word-break:break-all;\">{{ $json.lead_id }}</td> </tr> <tr> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;color:#6b7785;\">Name</td> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;font-weight:bold;\">{{ $json.first_name }} {{ $json.last_name }}</td> </tr> <tr> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;color:#6b7785;\">Email</td> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;\"> <a href=\"mailto:{{ $json.email }}\" style=\"color:#1f4fd8;text-decoration:none;\">{{ $json.email }}</a> </td> </tr> <tr> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;color:#6b7785;\">Phone</td> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;\"> <a href=\"tel:{{ $json.phone }}\" style=\"color:#1f4fd8;text-decoration:none;\">{{ $json.phone }}</a> </td> </tr> <tr> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;color:#6b7785;\">Company</td> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;\">{{ $json.company }}</td> </tr> <tr> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;color:#6b7785;\">Received</td> <td style=\"padding:10px 0;border-bottom:1px solid #eef1f4;\">{{ DateTime.fromISO($json.received_at, { setZone: true }).toFormat('MMM d, yyyy, h:mm a ZZZZ') }}</td> </tr> <tr> <td style=\"padding:10px 0;color:#6b7785;vertical-align:top;\">Message</td> <td style=\"padding:10px 0;color:#9aa5b1;font-style:italic;\">{{ $json.message || 'No message provided' }}</td> </tr> </table> </td> </tr> <tr> <td align=\"center\" style=\"padding:0 32px 32px;\"> <a href=\"mailto:{{ $json.email }}\" style=\"display:inline-block;background-color:#1f4fd8;color:#ffffff;font-size:14px;font-weight:bold;text-decoration:none;padding:12px 28px;border-radius:6px;\">Reply to Lead</a> </td> </tr> <tr> <td style=\"background-color:#f9fafb;padding:16px 32px;border-top:1px solid #e3e8ee;\"> <p style=\"margin:0;font-size:12px;color:#9aa5b1;line-height:18px;\"> This is an automated notification. Lead ID: {{ $json.lead_id }} </p> </td> </tr> </table> </td> </tr> </table> </body> </html>"
}
